type Room={id:string;code:string;name:string;building:string|null;floor:string|null;capacity:number|null;condition:string;status:string;notes:string|null;created_at:string};
type Item={id:string;item_type:"asset"|"consumable";name:string;brand:string;model:string|null;category:string|null;inventory_code:string|null;serial_number:string|null;room_id:string|null;unit:string;quantity:number;min_stock:number;condition:string;status:string;acquired_at:string|null;acquisition_source:string|null;acquisition_price:number;custodian_staff_id:string|null;notes:string|null;created_at:string};
type RequestRow={id:string;kind:string;item_id:string|null;room_id:string|null;requester_user_id:string|null;requester_name:string;quantity:number;purpose:string;start_at:string|null;end_at:string|null;priority:string;status:string;approved_by:string|null;approved_at:string|null;returned_at:string|null;notes:string|null;created_at:string};
type Maintenance={id:string;item_id:string;issue:string;action:string|null;vendor:string|null;cost:number;priority:string;status:string;due_at:string|null;completed_at:string|null;notes:string|null;created_at:string};
type Procurement={id:string;item_type:"asset"|"consumable";item_name:string;brand:string;model:string|null;category:string|null;vendor:string|null;quantity:number;unit:string;unit_price:number;fund_source:string|null;status:string;ordered_at:string|null;received_at:string|null;notes:string|null;created_at:string};
