type Movement={id:string;item_id:string;from_room_id:string|null;to_room_id:string|null;reason:string;moved_at:string};

const today=()=>new Date().toLocaleDateString("en-CA",{timeZone:"Asia/Jakarta"});
const localDateTime=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);
const money=(n:number)=>new Intl.NumberFormat("id-ID",{style:"currency",currency:"IDR",maximumFractionDigits:0}).format(Number(n)||0);
const unique=(values:(string|null|undefined)[])=>Array.from(new Set(values.map(x=>String(x||"").trim()).filter(Boolean))).sort((a,b)=>a.localeCompare(b,"id"));
const label=(v:string)=>({
 asset:"Aset",consumable:"Habis Pakai",available:"Tersedia",active:"Aktif",loaned:"Dipinjam",maintenance:"Perawatan",lost:"Hilang",inactive:"Nonaktif",archived:"Arsip",
 item_loan:"Peminjaman Barang",room_loan:"Peminjaman Ruang",repair:"Perbaikan",procurement:"Pengadaan",stock_request:"Permintaan Stok",
 submitted:"Diajukan",approved:"Disetujui",rejected:"Ditolak",borrowed:"Dipinjam",returned:"Dikembalikan",in_progress:"Diproses",completed:"Selesai",cancelled:"Dibatalkan",
 low:"Rendah",normal:"Normal",high:"Tinggi",urgent:"Darurat",open:"Terbuka",scheduled:"Terjadwal",requested:"Diajukan",ordered:"Dipesan",received:"Diterima",
 draft:"Draf",review:"Review",matched:"Cocok",quantity_mismatch:"Jumlah Berbeda",condition_changed:"Kondisi Berubah",missing:"Tidak Ditemukan",moved:"Berpindah",unchecked:"Belum Dicek"
} as Record<string,string>)[v]||v;

